38	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
39	function generateTeaserScore(url: string): number {
40	  let hash = 0;
41	  for (let i = 0; i < url.length; i++) {
42	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
43	  }
44	  return 45 + (Math.abs(hash) % 28);
45	}
