393	                        </TableCell>
394	
395	                        {/* Score */}
396	                        <TableCell>
397	                          {scan.overall_score !== null ? (
398	                            <div className="flex items-center gap-2">
399	                              <ScoreRing score={scan.overall_score} size={28} strokeWidth={3} showLabel={false} />
400	                              <span className={cn("text-sm font-semibold tabular-nums", getScoreColor(scan.overall_score))}>
