431	                            {getStatusBadge(scan.status)}
432	                            {canMonitor && isMonitored(scan.url) && (
433	                              <Bell className="h-3 w-3 text-primary" />
434	                            )}
435	                          </div>
436	                        </TableCell>
437	
438	                        {/* Date */}
439	                        <TableCell className="text-sm text-muted-foreground">
440	                          {formatDate(scan.created_at)}
441	                        </TableCell>
442	
443	                        {/* Actions */}
444	                        <TableCell className="pr-5">
445	                          <DropdownMenu>
446	                            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
447	                              <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
448	                                <MoreVertical className="h-4 w-4 text-muted-foreground" />
449	                              </Button>
450	                            </DropdownMenuTrigger>
451	                            <DropdownMenuContent align="end">
452	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); router.push(`/reports/${scan.id}`); }}>
453	                                <Eye className="mr-2 h-3.5 w-3.5" /> View Report
454	                              </DropdownMenuItem>
455	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); router.push(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`); }}>
456	                                <RefreshCw className="mr-2 h-3.5 w-3.5" /> Re-scan
457	                              </DropdownMenuItem>
458	                              <DropdownMenuSeparator />
459	                              {canMonitor ? (
460	                                <DropdownMenuItem
461	                                  onClick={(e) => {
462	                                    e.stopPropagation();
463	                                    const urlHash = computeUrlHash(scan.url);
464	                                    const existing = monitoredUrls.find((m) => m.url_hash === urlHash);
465	                                    if (existing) {
466	                                      removeMonitoredUrl.mutate(existing.id, {
467	                                        onSuccess: () => toast.success("Monitoring disabled for this URL"),
468	                                        onError: () => toast.error("Failed to update monitoring"),
469	                                      });
470	                                    } else {
471	                                      addMonitoredUrl.mutate(
472	                                        { url: scan.url, frequency: "monthly", alert_threshold: 5 },
473	                                        {
474	                                          onSuccess: () => toast.success("Monthly monitoring enabled — you'll get alerts when the score drops"),
475	                                          onError: () => toast.error("Failed to enable monitoring"),
476	                                        }
477	                                      );
478	                                    }
479	                                  }}
480	                                >
481	                                  {isMonitored(scan.url) ? (
482	                                    <><BellOff className="mr-2 h-3.5 w-3.5 text-muted-foreground" />Stop Monitoring</>
483	                                  ) : (
484	                                    <><Bell className="mr-2 h-3.5 w-3.5" />Monitor Monthly</>
485	                                  )}
486	                                </DropdownMenuItem>
487	                              ) : (
488	                                <DropdownMenuItem disabled className="opacity-50">
489	                                  <Bell className="mr-2 h-3.5 w-3.5" />
490	                                  Monitor Monthly
491	                                  <Badge variant="outline" className="ml-auto text-2xs border-amber-200 bg-amber-50 text-amber-700">Pro</Badge>
492	                                </DropdownMenuItem>
493	                              )}
494	                              <DropdownMenuSeparator />
495	                              <DropdownMenuItem
496	                                className="text-red-600"
497	                                onClick={(e) => {
498	                                  e.stopPropagation();
499	                                  handleDelete(scan.id, displayHostname);
500	                                }}
501	                              >
502	                                <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete
503	                              </DropdownMenuItem>
504	                            </DropdownMenuContent>
505	                          </DropdownMenu>
506	                        </TableCell>
507	                      </TableRow>
508	                    );
509	                  })}
510	                </TableBody>
511	              </Table>
512	            </div>
513	
514	            {/* Results count */}
515	            <div className="border-t border-border/30 bg-muted/10 px-5 py-3">
516	              <p className="text-xs text-muted-foreground">
517	                Showing {filtered.length} of {scans.length} report{scans.length !== 1 ? "s" : ""}
518	              </p>
519	            </div>
520	          </Card>
521	        ) : (
522	          <EmptyState
523	            icon={ScanLine}
524	            title="No reports found"
525	            description={
526	              hasActiveFilters
527	                ? "Try adjusting your filters to find what you're looking for."
528	                : "Run your first CRO audit to see results here."
529	            }
530	            actionLabel="Start New Scan"
531	            actionHref="/scan"
532	          />
533	        )}
534	      </div>
535	    </PageTransition>
536	  );
537	}
