1	import { SCORE_THRESHOLDS } from './constants'
2	import type { Severity, Effort, CroPillar, PageType, PillarResult } from '@/types'
3	
4	// ── Score Colors ─────────────────────────────────────────────
5	
6	export function getScoreColor(score: number): string {
7	  if (score < SCORE_THRESHOLDS.poor) return 'text-red-600'
8	  if (score < SCORE_THRESHOLDS.average) return 'text-amber-600'
9	  return 'text-green-600'
10	}
11	
12	export function getScoreBgColor(score: number): string {
13	  if (score < SCORE_THRESHOLDS.poor) return 'bg-red-500'
14	  if (score < SCORE_THRESHOLDS.average) return 'bg-amber-500'
15	  return 'bg-green-500'
16	}
17	
18	export function getScoreBgLight(score: number): string {
19	  if (score < SCORE_THRESHOLDS.poor) return 'bg-red-50'
20	  if (score < SCORE_THRESHOLDS.average) return 'bg-amber-50'
21	  return 'bg-green-50'
22	}
23	
24	export function getScoreHex(score: number): string {
25	  if (score < SCORE_THRESHOLDS.poor) return '#EF4444'
26	  if (score < SCORE_THRESHOLDS.average) return '#F59E0B'
27	  return '#22C55E'
28	}
29	
30	export function getScoreLabel(score: number): string {
31	  if (score < 20) return 'Critical'
32	  if (score < SCORE_THRESHOLDS.poor) return 'Poor'
33	  if (score < 55) return 'Below Average'
34	  if (score < SCORE_THRESHOLDS.average) return 'Average'
35	  if (score < 85) return 'Good'
36	  return 'Excellent'
37	}
38	
39	// ── Severity ─────────────────────────────────────────────────
40	
41	export function getSeverityColor(severity: Severity): {
42	  bg: string
43	  text: string
44	  border: string
45	  dot: string
46	} {
47	  switch (severity) {
48	    case 'critical':
49	      return { bg: 'bg-red-50', text: 'text-red-700', border: 'border-red-200', dot: 'bg-red-500' }
50	    case 'warning':
51	      return { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200', dot: 'bg-amber-500' }
52	    case 'info':
53	      return { bg: 'bg-blue-50', text: 'text-blue-700', border: 'border-blue-200', dot: 'bg-blue-500' }
54	    case 'passed':
55	      return { bg: 'bg-green-50', text: 'text-green-700', border: 'border-green-200', dot: 'bg-green-500' }
56	  }
57	}
58	
59	export function getSeverityLabel(severity: Severity): string {
60	  switch (severity) {
61	    case 'critical': return 'Critical'
62	    case 'warning': return 'Warning'
63	    case 'info': return 'Info'
64	    case 'passed': return 'Passed'
65	  }
66	}
67	
68	// ── Effort ───────────────────────────────────────────────────
69	
70	export function getEffortLabel(effort: Effort): string {
71	  switch (effort) {
72	    case 'quick': return 'Quick Win'
73	    case 'moderate': return 'Moderate'
74	    case 'significant': return 'Significant'
75	  }
76	}
77	
78	export function getEffortColor(effort: Effort): string {
79	  switch (effort) {
80	    case 'quick': return 'text-green-600 bg-green-50 border-green-200'
81	    case 'moderate': return 'text-amber-600 bg-amber-50 border-amber-200'
82	    case 'significant': return 'text-slate-600 bg-slate-50 border-slate-200'
83	  }
84	}
85	
86	// ── Weighted Scoring ─────────────────────────────────────────
87	
88	/** Pillar weights vary by page type — CTA matters more on landing pages */
89	const PAGE_TYPE_WEIGHTS: Record<PageType, Record<CroPillar, number>> = {
90	  landing: {
91	    value_proposition: 0.20, cta_effectiveness: 0.22, trust_signals: 0.18,
92	    visual_hierarchy: 0.10, mobile_experience: 0.12, content_copy: 0.10, page_performance: 0.08,
93	  },
94	  product: {
95	    value_proposition: 0.12, cta_effectiveness: 0.18, trust_signals: 0.22,
96	    visual_hierarchy: 0.10, mobile_experience: 0.15, content_copy: 0.13, page_performance: 0.10,
97	  },
98	  homepage: {
99	    value_proposition: 0.22, cta_effectiveness: 0.15, trust_signals: 0.15,
100	    visual_hierarchy: 0.15, mobile_experience: 0.12, content_copy: 0.12, page_performance: 0.09,
101	  },
102	  pricing: {
103	    value_proposition: 0.15, cta_effectiveness: 0.20, trust_signals: 0.22,
104	    visual_hierarchy: 0.12, mobile_experience: 0.10, content_copy: 0.13, page_performance: 0.08,
105	  },
106	  signup: {
107	    value_proposition: 0.18, cta_effectiveness: 0.25, trust_signals: 0.20,
108	    visual_hierarchy: 0.08, mobile_experience: 0.15, content_copy: 0.08, page_performance: 0.06,
109	  },
110	  blog: {
111	    value_proposition: 0.10, cta_effectiveness: 0.12, trust_signals: 0.08,
112	    visual_hierarchy: 0.15, mobile_experience: 0.15, content_copy: 0.25, page_performance: 0.15,
113	  },
114	  other: {
115	    value_proposition: 0.15, cta_effectiveness: 0.15, trust_signals: 0.15,
116	    visual_hierarchy: 0.14, mobile_experience: 0.14, content_copy: 0.14, page_performance: 0.13,
117	  },
118	}
119	
120	export function getPillarWeight(pillar: CroPillar, pageType: PageType): number {
121	  return PAGE_TYPE_WEIGHTS[pageType]?.[pillar] ?? 0.14
122	}
123	
124	export function calculateWeightedScore(results: PillarResult[], pageType: PageType): number {
125	  let totalWeight = 0
126	  let weightedSum = 0
127	  for (const r of results) {
128	    const w = getPillarWeight(r.pillar, pageType)
129	    weightedSum += r.score * w
130	    totalWeight += w
131	  }
132	  return totalWeight > 0 ? Math.round(weightedSum / totalWeight) : 0
133	}
134	
135	// ── Industry Benchmarks ──────────────────────────────────────
136	
137	const INDUSTRY_BENCHMARKS: Record<CroPillar, number> = {
138	  value_proposition: 62,
139	  cta_effectiveness: 55,
140	  trust_signals: 48,
141	  visual_hierarchy: 67,
142	  mobile_experience: 58,
143	  content_copy: 60,
144	  page_performance: 72,
145	}
146	
147	export function getIndustryBenchmark(pillar: CroPillar): number {
148	  return INDUSTRY_BENCHMARKS[pillar]
149	}
150	
151	/** Returns percentile rank (0-100) — how this score compares to all scans */
152	export function getPercentileRank(score: number): number {
153	  if (score >= 90) return 97
154	  if (score >= 80) return 88
155	  if (score >= 70) return 72
156	  if (score >= 60) return 55
157	  if (score >= 50) return 38
158	  if (score >= 40) return 22
159	  if (score >= 30) return 12
160	  return 5
161	}
162	
163	export function formatScore(score: number): string {
164	  return Math.round(score).toString()
165	}
166	
167	export function getPercentileLabel(score: number, benchmark: number): { label: string; color: string } {
168	  const diff = score - benchmark
169	  if (diff >= 15) return { label: 'Top 10%', color: 'text-green-600' }
170	  if (diff >= 8) return { label: 'Top 25%', color: 'text-green-600' }
171	  if (diff >= 0) return { label: 'Above Average', color: 'text-emerald-600' }
172	  if (diff >= -8) return { label: 'Below Average', color: 'text-amber-600' }
173	  if (diff >= -15) return { label: 'Bottom 25%', color: 'text-red-500' }
174	  return { label: 'Bottom 10%', color: 'text-red-600' }
175	}
176	
177	// ── Time Helpers ─────────────────────────────────────────────
178	
179	export function getTimeGreeting(): string {
180	  const hour = new Date().getHours()
181	  if (hour < 12) return 'Good morning'
182	  if (hour < 17) return 'Good afternoon'
183	  return 'Good evening'
184	}
185	
186	export function formatRelativeDate(dateStr: string): string {
187	  const now = new Date()
188	  const date = new Date(dateStr)
189	  const diffMs = now.getTime() - date.getTime()
190	  const diffMins = Math.floor(diffMs / 60000)
191	  const diffHours = Math.floor(diffMs / 3600000)
192	  const diffDays = Math.floor(diffMs / 86400000)
193	
194	  if (diffMins < 1) return 'Just now'
195	  if (diffMins < 60) return `${diffMins}m ago`
196	  if (diffHours < 24) return `${diffHours}h ago`
197	  if (diffDays < 7) return `${diffDays}d ago`
198	  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
199	}
