'use client'

import { useState, useEffect } from "react"

interface ChartColors {
  primary: string
  success: string
  danger: string
  warning: string
  info: string
  gridLines: string
  axisText: string
  tooltipBg: string
  tooltipBorder: string
}

function resolveVar(prop: string): string {
  if (typeof window === "undefined") return ""
  return getComputedStyle(document.documentElement).getPropertyValue(prop).trim()
}

function getColors(): ChartColors {
  return {
    primary:      resolveVar("--color-primary"),
    success:      resolveVar("--color-success-default"),
    danger:       resolveVar("--color-danger-default"),
    warning:      resolveVar("--color-warning-default"),
    info:         resolveVar("--color-info-default"),
    gridLines:    resolveVar("--color-border-subtle"),
    axisText:     resolveVar("--color-fg-tertiary"),
    tooltipBg:    resolveVar("--color-overlay"),
    tooltipBorder:resolveVar("--color-border-default"),
  }
}

const FALLBACKS: ChartColors = {
  primary:       "oklch(62% 0.21 264)",
  success:       "oklch(56% 0.19 145)",
  danger:        "oklch(51% 0.22 27)",
  warning:       "oklch(65% 0.18 72)",
  info:          "oklch(58% 0.18 230)",
  gridLines:     "oklch(95% 0.006 220)",
  axisText:      "oklch(55% 0.007 220)",
  tooltipBg:     "oklch(100% 0 0)",
  tooltipBorder: "oklch(91% 0.010 220)",
}

export function useChartColors(): ChartColors {
  const [colors, setColors] = useState<ChartColors>(FALLBACKS)

  useEffect(() => {
    const resolved = getColors()
    // Only update if we got real values (not empty strings from SSR)
    const hasValues = Object.values(resolved).some((v) => v !== "")
    if (hasValues) setColors(resolved)

    // Re-resolve on theme change
    const observer = new MutationObserver(() => {
      const updated = getColors()
      setColors(updated)
    })
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    })
    return () => observer.disconnect()
  }, [])

  return colors
}

'use client'

import React, { useEffect, useState } from "react"
import { getScoreLabel } from "@/lib/score-utils"
import { cn } from "@/lib/utils"

type ScoreRingVariant = "hero" | "pillar" | "mini"

interface ScoreRingProps {
  score: number
  variant?: ScoreRingVariant
  /** Override size in px — overrides variant default */
  size?: number
  /** Override strokeWidth — overrides variant default */
  strokeWidth?: number
  showLabel?: boolean
  className?: string
}

const VARIANT_DEFAULTS: Record<ScoreRingVariant, { size: number; strokeWidth: number }> = {
  hero:   { size: 180, strokeWidth: 10 },
  pillar: { size: 80,  strokeWidth: 6  },
  mini:   { size: 48,  strokeWidth: 4  },
}

function getScoreColorVar(score: number): string {
  if (score >= 70) return "--color-success-default"
  if (score >= 40) return "--color-warning-default"
  return "--color-danger-default"
}

function resolveColor(cssVar: string): string {
  if (typeof window === "undefined") {
    // SSR fallbacks
    if (cssVar === "--color-success-default") return "#22c55e"
    if (cssVar === "--color-warning-default") return "#f59e0b"
    return "#ef4444"
  }
  return getComputedStyle(document.documentElement).getPropertyValue(cssVar).trim()
}

export const ScoreRing = React.forwardRef<HTMLDivElement, ScoreRingProps>(function ScoreRing(
  { score, variant = "mini", size: sizeProp, strokeWidth: swProp, showLabel = true, className },
  ref
) {
  const defaults = VARIANT_DEFAULTS[variant]
  const size = sizeProp ?? defaults.size
  const strokeWidth = swProp ?? defaults.strokeWidth

  const [animatedOffset, setAnimatedOffset] = useState(0)
  const [color, setColor] = useState("#94a3b8")

  const radius = (size - strokeWidth) / 2
  const circumference = 2 * Math.PI * radius
  const targetOffset = circumference * (1 - score / 100)
  const label = getScoreLabel(score)
  const center = size / 2
  const fontSize = size * 0.28
  const labelSize = size * 0.09
  const colorVar = getScoreColorVar(score)

  useEffect(() => {
    setAnimatedOffset(circumference)
    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50)
    return () => clearTimeout(timer)
  }, [score, circumference, targetOffset])

  useEffect(() => {
    setColor(resolveColor(colorVar))
  }, [colorVar, score])

  const glowShadow = `drop-shadow(0 0 6px color-mix(in oklch, var(${colorVar}) 25%, transparent))`

  return (
    <div
      ref={ref}
      role="img"
      aria-label={`CRO Score: ${score} out of 100`}
      className={cn("relative inline-flex flex-col items-center", className)}
    >
      <div
        className="absolute rounded-full"
        style={{
          width: size,
          height: size,
          background: `radial-gradient(circle, color-mix(in oklch, var(${colorVar}) 8%, transparent) 0%, transparent 70%)`,
        }}
      />
      <svg
        width={size}
        height={size}
        className="transform -rotate-90"
        style={{ filter: glowShadow }}
      >
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          className="text-muted/60"
        />
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={animatedOffset}
          style={{ transition: "stroke-dashoffset 1s ease-out" }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span
          className="font-bold text-foreground tabular-nums"
          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
        >
          {score}
        </span>
        {size >= 60 && (
          <span
            className="text-muted-foreground"
            style={{ fontSize: `${labelSize}px` }}
          >
            /100
          </span>
        )}
      </div>
      {showLabel && size >= 60 && (
        <span className="mt-1 text-xs font-medium" style={{ color }}>
          {label}
        </span>
      )}
    </div>
  )
})

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  LayoutDashboard,
  ScanLine,
  FileText,
  Puzzle,
  Settings,
  Zap,
  TrendingUp,
  Swords,
  Code2,
  Gift,
  Activity,
} from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Progress } from '@/components/ui/progress'
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from '@/components/ui/sidebar'
import { Separator } from '@/components/ui/separator'
import { useAuth } from '@/contexts/AuthContext'
import { useFeatureFlag } from '@/hooks/use-feature-flag'
import { useTeams } from '@/hooks/use-teams'
import { TeamSwitcher } from '@/components/team/TeamSwitcher'
import { isProPlus } from '@/types/index'
import { cn } from '@/lib/utils'

interface NavItem {
  title: string
  url: string
  icon: React.ElementType
  flagKey?: string
  proOnly?: boolean
}

interface NavGroup {
  label?: string
  items: NavItem[]
}

const NAV_GROUPS: NavGroup[] = [
  {
    label: undefined,
    items: [
      { title: 'Dashboard', url: '/dashboard', icon: LayoutDashboard },
      { title: 'New Scan',  url: '/scan',      icon: ScanLine },
    ],
  },
  {
    label: 'ANALYZE',
    items: [
      { title: 'My Reports',    url: '/reports',     icon: FileText },
      { title: 'Score History', url: '/history',     icon: TrendingUp },
      { title: 'Competitors',   url: '/competitors', icon: Swords },
    ],
  },
  {
    label: 'MANAGE',
    items: [
      { title: 'Integrations', url: '/integrations', icon: Puzzle, flagKey: 'integrations_enabled' },
      { title: 'Monitoring',   url: '/monitoring',   icon: Activity, proOnly: true },
    ],
  },
  {
    label: undefined,
    items: [
      { title: 'Refer & Earn', url: '/referrals',    icon: Gift },
      { title: 'API',          url: '/api-settings', icon: Code2, proOnly: true },
      { title: 'Settings',     url: '/settings',     icon: Settings },
    ],
  },
]

export function AppSidebar() {
  const { state } = useSidebar()
  const collapsed = state === 'collapsed'
  const pathname = usePathname()
  const { profile } = useAuth()
  const { data: teams } = useTeams()
  const showTeamSwitcher =
    !collapsed && profile && isProPlus(profile.plan) && (teams?.length ?? 0) >= 0

  const integrationsEnabled = useFeatureFlag('integrations_enabled', true)

  const isActive = (path: string) =>
    pathname === path || pathname.startsWith(path + '/')

  const filterItems = (items: NavItem[]) =>
    items.filter((item) => {
      if (item.flagKey === 'integrations_enabled') return integrationsEnabled
      if (item.proOnly && profile) return isProPlus(profile.plan)
      return true
    })

  const scansUsed = profile?.scans_used ?? 0
  const scanLimit = profile?.scan_limit ?? 3
  const usagePercent = Math.round((scansUsed / scanLimit) * 100)

  return (
    <Sidebar collapsible="icon" className="border-r-0" aria-label="Main navigation">
      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
        <Link
          href="/dashboard"
          className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full"
        >
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
            <ScanLine className="h-3.5 w-3.5 text-white" />
          </div>
          {!collapsed && (
            <span className="text-base font-semibold tracking-tight text-[--sidebar-foreground-active]">
              ConvertScan
            </span>
          )}
        </Link>
        {showTeamSwitcher && (
          <div className="mt-3 -mx-1">
            <TeamSwitcher />
          </div>
        )}
      </SidebarHeader>

      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
        {NAV_GROUPS.map((group, gi) => {
          const visibleItems = filterItems(group.items)
          if (visibleItems.length === 0) return null

          return (
            <SidebarGroup key={gi}>
              {group.label && !collapsed && (
                <SidebarGroupLabel className="text-2xs uppercase tracking-widest text-sidebar-foreground/40 px-3 py-1.5 mt-2">
                  {group.label}
                </SidebarGroupLabel>
              )}
              <SidebarGroupContent>
                <SidebarMenu className="space-y-0.5">
                  {visibleItems.map((item) => {
                    const active = isActive(item.url)
                    return (
                      <SidebarMenuItem key={item.title}>
                        <SidebarMenuButton
                          asChild
                          tooltip={item.title}
                          isActive={active}
                          className={cn(
                            'h-9 transition-colors duration-150 relative rounded-md',
                            active
                              ? 'bg-white/10 text-[--sidebar-foreground-active] before:absolute before:left-0 before:top-2 before:bottom-2 before:w-0.5 before:rounded-full before:bg-[--sidebar-primary]'
                              : 'text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground'
                          )}
                        >
                          <Link href={item.url}>
                            <item.icon
                              className={cn(
                                'h-[18px] w-[18px] shrink-0',
                                active ? 'text-[--sidebar-foreground-active]' : 'text-sidebar-foreground/60'
                              )}
                            />
                            <span className="text-sm font-medium">{item.title}</span>
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    )
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          )
        })}
      </SidebarContent>

      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
        {/* Scan usage indicator — expanded only */}
        {!collapsed && (
          <div className="mb-3 rounded-lg bg-white/5 p-3">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-xs text-sidebar-foreground/40">Scans used</span>
              <span className="text-xs font-medium text-sidebar-foreground/70 tabular-nums">
                {profile ? `${scansUsed}/${scanLimit}` : '\u2014'}
              </span>
            </div>
            <Progress value={profile ? usagePercent : 0} className="h-0.5" />
            <div className="mt-1.5">
              <Badge
                variant="outline"
                className="border-white/10 bg-transparent text-2xs text-sidebar-foreground/40 capitalize px-1.5 py-0"
              >
                {profile?.plan ?? 'free'} plan
              </Badge>
            </div>
          </div>
        )}

        {/* Separator — hidden when collapsed */}
        {!collapsed && <Separator className="mb-3 bg-white/5" />}

        {profile?.plan !== 'agency' && profile?.plan !== 'pro' && (
          !collapsed ? (
            <Link
              href="/pricing"
              className="flex items-center justify-center gap-2 rounded-md bg-sidebar-primary px-4 py-2.5 text-sm font-semibold text-white transition-all hover:opacity-90"
            >
              <Zap className="h-4 w-4" />
              Upgrade Plan
            </Link>
          ) : (
            <Link
              href="/pricing"
              aria-label="Upgrade Plan"
              className="flex h-9 w-9 items-center justify-center rounded-md bg-sidebar-primary text-white transition-opacity hover:opacity-90"
            >
              <Zap className="h-4 w-4" />
            </Link>
          )
        )}
      </SidebarFooter>
    </Sidebar>
  )
}

