'use client'

import React, { useEffect, useState, useCallback } from "react"
import { useRouter } from "next/navigation"
import {
  LayoutDashboard,
  ScanLine,
  FileText,
  TrendingUp,
  Swords,
  Settings,
  Moon,
  Sun,
  LogOut,
  Zap,
  Code2,
  Gift,
} from "lucide-react"
import { useTheme } from "next-themes"
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { useAuth } from "@/contexts/AuthContext"

interface CommandEntry {
  label: string
  icon: React.ElementType
  action: () => void
  shortcut?: string
}

export function CommandPalette() {
  const [open, setOpen] = useState(false)
  const router = useRouter()
  const { theme, setTheme } = useTheme()
  const { signOut } = useAuth()

  const navigate = useCallback(
    (path: string) => {
      router.push(path)
      setOpen(false)
    },
    [router]
  )

  // Cmd+K global listener
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        setOpen((prev) => !prev)
      }
    }
    document.addEventListener("keydown", down)
    return () => document.removeEventListener("keydown", down)
  }, [])

  const NAV_ITEMS: CommandEntry[] = [
    { label: "Dashboard",     icon: LayoutDashboard, action: () => navigate("/dashboard") },
    { label: "New Scan",      icon: ScanLine,        action: () => navigate("/scan"),       shortcut: "N" },
    { label: "My Reports",    icon: FileText,        action: () => navigate("/reports") },
    { label: "Score History", icon: TrendingUp,      action: () => navigate("/history") },
    { label: "Competitors",   icon: Swords,          action: () => navigate("/competitors") },
    { label: "Integrations",  icon: Zap,             action: () => navigate("/integrations") },
    { label: "Refer & Earn",  icon: Gift,            action: () => navigate("/referrals") },
    { label: "API Settings",  icon: Code2,           action: () => navigate("/api-settings") },
    { label: "Settings",      icon: Settings,        action: () => navigate("/settings"),   shortcut: "," },
  ]

  const SYSTEM_ITEMS: CommandEntry[] = [
    {
      label: `Switch to ${theme === "dark" ? "Light" : "Dark"} Mode`,
      icon: theme === "dark" ? Sun : Moon,
      action: () => { setTheme(theme === "dark" ? "light" : "dark"); setOpen(false) },
    },
    {
      label: "Sign Out",
      icon: LogOut,
      action: async () => { setOpen(false); await signOut(); router.replace("/login") },
    },
  ]

  return (
    <CommandDialog open={open} onOpenChange={setOpen}>
      <CommandInput placeholder="Search pages, actions..." />
      <CommandList>
        <CommandEmpty>No results found.</CommandEmpty>
        <CommandGroup heading="Navigate">
          {NAV_ITEMS.map((item) => (
            <CommandItem
              key={item.label}
              onSelect={item.action}
              className="gap-2"
            >
              <item.icon className="h-4 w-4 text-muted-foreground" />
              <span>{item.label}</span>
              {item.shortcut && (
                <kbd className="ml-auto text-2xs text-muted-foreground border border-border rounded px-1 py-0.5">
                  {item.shortcut}
                </kbd>
              )}
            </CommandItem>
          ))}
        </CommandGroup>
        <CommandSeparator />
        <CommandGroup heading="System">
          {SYSTEM_ITEMS.map((item) => (
            <CommandItem
              key={item.label}
              onSelect={item.action}
              className="gap-2"
            >
              <item.icon className="h-4 w-4 text-muted-foreground" />
              <span>{item.label}</span>
            </CommandItem>
          ))}
        </CommandGroup>
      </CommandList>
    </CommandDialog>
  )
}

