'use client';

import { motion } from "framer-motion";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { EmptyState } from "@/components/shared/EmptyState";
import { ChartErrorBoundary } from "@/components/shared/ChartErrorBoundary";
import { useChartColors } from "@/hooks/use-chart-colors";
import { TrendingUp } from "lucide-react";

export interface ScoreTrendPoint {
  date: string;
  score: number;
}

interface ScoreTrendChartProps {
  data: ScoreTrendPoint[];
}

export function ScoreTrendChart({ data }: ScoreTrendChartProps) {
  const hasData = data.length >= 2;
  const colors = useChartColors();

  return (
    <Card className="border-border shadow-xs h-full">
      <CardHeader className="flex flex-row items-center justify-between pb-3">
        <CardTitle className="text-sm font-medium">Score Trend</CardTitle>
        <span className="text-xs text-muted-foreground">Last 8 weeks</span>
      </CardHeader>
      <CardContent className="pb-4">
        {!hasData ? (
          <div className="flex h-[200px] items-center justify-center">
            <EmptyState
              icon={TrendingUp}
              title="Not enough data yet"
              description="Complete at least 2 scans to see your score trend."
              className="py-0"
            />
          </div>
        ) : (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            role="img"
            aria-label="Score trend chart showing weekly CRO scores over the last 8 weeks"
          >
            <ChartErrorBoundary fallbackHeight={220}>
              <ResponsiveContainer width="100%" height={220}>
                <AreaChart
                  data={data}
                  margin={{ top: 8, right: 8, bottom: 0, left: -20 }}
                >
                  <defs>
                    <linearGradient id="scoreTrendFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={colors.primary} stopOpacity={0.18} />
                      <stop offset="100%" stopColor={colors.primary} stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <XAxis
                    dataKey="date"
                    tick={{ fontSize: 11, fill: colors.axisText }}
                    axisLine={false}
                    tickLine={false}
                    interval="preserveStartEnd"
                  />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11, fill: colors.axisText }}
                    axisLine={false}
                    tickLine={false}
                    tickCount={5}
                  />
                  <Tooltip
                    contentStyle={{
                      fontSize: 12,
                      borderRadius: 8,
                      border: `1px solid ${colors.tooltipBorder}`,
                      background: colors.tooltipBg,
                      boxShadow: "var(--shadow-md)",
                    }}
                    formatter={(value) => [`${String(value)}/100`, "Score"]}
                    labelStyle={{ fontWeight: 600, marginBottom: 2 }}
                  />
                  <ReferenceLine
                    y={70}
                    stroke={colors.success}
                    strokeDasharray="4 4"
                    strokeWidth={1}
                    label={{
                      value: "Good",
                      position: "insideTopRight",
                      fontSize: 10,
                      fill: colors.success,
                    }}
                  />
                  <Area
                    type="monotone"
                    dataKey="score"
                    stroke={colors.primary}
                    strokeWidth={2}
                    fill="url(#scoreTrendFill)"
                    dot={{ r: 3, fill: colors.primary, strokeWidth: 0 }}
                    activeDot={{ r: 5, fill: colors.primary, strokeWidth: 2, stroke: colors.tooltipBg }}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </ChartErrorBoundary>
          </motion.div>
        )}
      </CardContent>
    </Card>
  );
}

