'use client';

import { motion } from "framer-motion";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
} from "recharts";
import { TrendingUp } from "lucide-react";
import { EmptyState } from "@/components/shared/EmptyState";
import { ChartErrorBoundary } from "@/components/shared/ChartErrorBoundary";
import { useChartColors } from "@/hooks/use-chart-colors";

// ── Date formatting helper ───────────────────────────────────────

const MONTH_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function formatChartDate(dateStr: string): string {
  const d = new Date(dateStr);
  return `${MONTH_ABBR[d.getMonth()]} ${d.getDate()}`;
}

// ── Types ────────────────────────────────────────────────────────

export interface ScoreHistoryPoint {
  date: string;
  score: number;
}

interface ScoreHistoryChartProps {
  data: ScoreHistoryPoint[];
  height?: number;
}

// ── Custom Tooltip ────────────────────────────────────────────────

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{ value: number }>;
  label?: string;
  colors: ReturnType<typeof useChartColors>;
}

function CustomTooltip({ active, payload, label, colors }: CustomTooltipProps) {
  if (!active || !payload?.length) return null;
  return (
    <div
      style={{
        fontSize: 12,
        borderRadius: 8,
        border: `1px solid ${colors.tooltipBorder}`,
        background: colors.tooltipBg,
        padding: "8px 12px",
      }}
    >
      <p style={{ fontWeight: 600, marginBottom: 2 }}>{label ? formatChartDate(label) : ""}</p>
      <p style={{ color: colors.primary }}>{payload[0]?.value ?? 0}/100</p>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────

export function ScoreHistoryChart({ data, height = 200 }: ScoreHistoryChartProps) {
  const hasData = data.length >= 2;
  const colors = useChartColors();

  if (!hasData) {
    return (
      <div style={{ height }}>
        <EmptyState
          icon={TrendingUp}
          title="Not enough data yet"
          description="Run more scans to see your score trend."
          className="py-0 h-full flex items-center justify-center"
        />
      </div>
    );
  }

  const chartData = data.map((d) => ({
    date: d.date,
    label: formatChartDate(d.date),
    score: d.score,
  }));

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4, ease: "easeOut" }}
      role="img"
      aria-label="Score history chart showing CRO scores over time"
    >
      <ChartErrorBoundary fallbackHeight={height}>
        <ResponsiveContainer width="100%" height={height}>
          <AreaChart
            data={chartData}
            margin={{ top: 8, right: 8, bottom: 0, left: -20 }}
          >
            <defs>
              <linearGradient id="scoreHistoryFill" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={colors.primary} stopOpacity={0.18} />
                <stop offset="100%" stopColor={colors.primary} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis
              dataKey="label"
              tick={{ fontSize: 11, fill: colors.axisText }}
              axisLine={false}
              tickLine={false}
              interval="preserveStartEnd"
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 11, fill: colors.axisText }}
              axisLine={false}
              tickLine={false}
              tickCount={5}
            />
            <Tooltip content={<CustomTooltip colors={colors} />} />
            <ReferenceLine
              y={70}
              stroke={colors.success}
              strokeDasharray="4 4"
              strokeWidth={1}
              label={{
                value: "Good",
                position: "insideTopRight",
                fontSize: 10,
                fill: colors.success,
              }}
            />
            <Area
              type="monotone"
              dataKey="score"
              stroke={colors.primary}
              strokeWidth={2}
              fill="url(#scoreHistoryFill)"
              dot={{ r: 3, fill: colors.primary, strokeWidth: 0 }}
              activeDot={{ r: 5, fill: colors.primary, strokeWidth: 2, stroke: colors.tooltipBg }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </ChartErrorBoundary>
    </motion.div>
  );
}

