'use client';

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  LabelList,
  Cell,
} from "recharts";
import { cn } from "@/lib/utils";
import { ChartErrorBoundary } from "@/components/shared/ChartErrorBoundary";
import { useChartColors } from "@/hooks/use-chart-colors";
import type { PillarDelta } from "@/hooks/use-scan-comparison";

// ── Pillar abbreviations ──────────────────────────────────────────

const PILLAR_SHORT: Record<string, string> = {
  value_proposition: "Value",
  cta_effectiveness: "CTA",
  trust_signals: "Trust",
  visual_hierarchy: "Visual",
  mobile_experience: "Mobile",
  content_copy: "Copy",
  page_performance: "Perf",
};

// ── Custom Tooltip ────────────────────────────────────────────────

interface TooltipProps {
  active?: boolean;
  payload?: Array<{ name: string; value: number }>;
  label?: string;
  colors: ReturnType<typeof useChartColors>;
}

function CustomTooltip({ active, payload, label, colors }: TooltipProps) {
  if (!active || !payload?.length) return null;
  return (
    <div
      style={{
        fontSize: 12,
        borderRadius: 8,
        border: `1px solid ${colors.tooltipBorder}`,
        background: colors.tooltipBg,
        padding: "8px 12px",
      }}
    >
      <p style={{ fontWeight: 600, marginBottom: 4 }}>{label}</p>
      {payload.map((entry) => (
        <p key={entry.name} style={{ color: entry.name === "previous" ? colors.gridLines : colors.primary }}>
          {entry.name === "previous" ? "Previous" : "Current"}: {entry.value}
        </p>
      ))}
    </div>
  );
}

// ── Delta label ───────────────────────────────────────────────────

interface DeltaBadgeProps {
  delta: number;
}

function DeltaBadge({ delta }: DeltaBadgeProps) {
  if (delta === 0) return null;
  const isPos = delta > 0;
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full px-1.5 py-0 text-2xs font-bold",
        isPos
          ? "bg-[--color-success-subtle] text-[--color-success-fg]"
          : "bg-[--color-danger-subtle] text-[--color-danger-fg]"
      )}
    >
      {isPos ? `+${delta}` : delta}
    </span>
  );
}

// ── Props ─────────────────────────────────────────────────────────

interface PillarComparisonViewProps {
  pillarDeltas: PillarDelta[];
}

// ── Main Component ────────────────────────────────────────────────

export function PillarComparisonView({ pillarDeltas }: PillarComparisonViewProps) {
  const colors = useChartColors();

  if (pillarDeltas.length === 0) return null;

  const chartData = pillarDeltas.map((d) => ({
    pillar: PILLAR_SHORT[d.pillar] ?? d.pillar,
    previous: d.previous,
    current: d.current,
    delta: d.delta,
  }));

  return (
    <div>
      {/* Legend */}
      <div className="mb-3 flex items-center gap-4 text-xs text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: colors.gridLines }} />
          Previous
        </span>
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: colors.primary }} />
          Current
        </span>
      </div>

      <ChartErrorBoundary fallbackHeight={200}>
        <ResponsiveContainer width="100%" height={200}>
          <BarChart
            data={chartData}
            margin={{ top: 16, right: 8, bottom: 0, left: -20 }}
            barCategoryGap="30%"
            barGap={2}
          >
            <XAxis
              dataKey="pillar"
              tick={{ fontSize: 11, fill: colors.axisText }}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 11, fill: colors.axisText }}
              axisLine={false}
              tickLine={false}
              tickCount={5}
            />
            <Tooltip content={<CustomTooltip colors={colors} />} />
            <Bar dataKey="previous" name="previous" radius={[3, 3, 0, 0]} maxBarSize={28}>
              {chartData.map((_, i) => (
                <Cell key={i} fill={colors.gridLines} />
              ))}
              <LabelList dataKey="previous" position="top" style={{ fontSize: 9, fill: colors.axisText }} />
            </Bar>
            <Bar dataKey="current" name="current" radius={[3, 3, 0, 0]} maxBarSize={28}>
              {chartData.map((_, i) => (
                <Cell key={i} fill={colors.primary} />
              ))}
              <LabelList dataKey="current" position="top" style={{ fontSize: 9, fill: colors.primary }} />
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </ChartErrorBoundary>

      {/* Delta badges row */}
      <div className="mt-3 flex flex-wrap justify-around gap-2">
        {pillarDeltas.map((d) => (
          <div key={d.pillar} className="flex flex-col items-center gap-0.5">
            <span className="text-2xs text-muted-foreground">{PILLAR_SHORT[d.pillar] ?? d.pillar}</span>
            <DeltaBadge delta={d.delta} />
          </div>
        ))}
      </div>
    </div>
  );
}

