1	'use client';
2	
3	import {
4	  Radar,
5	  RadarChart,
6	  PolarGrid,
7	  PolarAngleAxis,
8	  PolarRadiusAxis,
9	  Tooltip,
10	  Legend,
11	  ResponsiveContainer,
12	} from "recharts";
13	import type { CroPillar } from "@/types";
14	import { CRO_PILLARS } from "@/lib/constants";
15	
16	// ── Chart colors — one per series ──────────────────────────────
17	const SERIES_COLORS = [
18	  "hsl(var(--primary))",
19	  "#f59e0b",
20	  "#10b981",
21	  "#ef4444",
22	  "#8b5cf6",
23	] as const;
24	
25	// ── Types ───────────────────────────────────────────────────────
26	
27	export interface RadarSeriesItem {
28	  name: string;
29	  scores: Partial<Record<CroPillar, number>>;
30	}
31	
32	interface CompetitorRadarChartProps {
33	  data: RadarSeriesItem[];
34	}
35	
36	// ── Recharts data shape ─────────────────────────────────────────
37	
38	interface RadarDataPoint {
39	  pillar: string;
40	  fullMark: number;
41	  [key: string]: string | number;
42	}
43	
44	function buildChartData(data: RadarSeriesItem[]): RadarDataPoint[] {
45	  return CRO_PILLARS.map((pillar) => {
46	    const point: RadarDataPoint = {
47	      pillar: pillar.label,
48	      fullMark: 100,
49	    };
50	    data.forEach((series) => {
51	      point[series.name] = series.scores[pillar.key] ?? 0;
52	    });
53	    return point;
54	  });
55	}
56	
57	// ── Custom tooltip ───────────────────────────────────────────────
58	
59	interface TooltipPayloadEntry {
60	  name: string;
61	  value: number;
62	  color: string;
63	}
64	
65	interface CustomTooltipProps {
66	  active?: boolean;
67	  payload?: TooltipPayloadEntry[];
68	  label?: string;
69	}
70	
71	function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
72	  if (!active || !payload?.length) return null;
73	
74	  return (
75	    <div className="rounded-lg border border-border/50 bg-popover px-3 py-2 shadow-md text-sm">
76	      <p className="mb-1.5 font-medium text-foreground">{label}</p>
77	      {payload.map((entry) => (
78	        <div key={entry.name} className="flex items-center gap-2">
79	          <span
80	            className="inline-block h-2 w-2 rounded-full shrink-0"
81	            style={{ background: entry.color }}
82	          />
83	          <span className="text-muted-foreground">{entry.name}:</span>
84	          <span className="font-medium tabular-nums text-foreground">{entry.value}</span>
85	        </div>
86	      ))}
87	    </div>
88	  );
89	}
90	
91	// ── Component ────────────────────────────────────────────────────
92	
93	export function CompetitorRadarChart({ data }: CompetitorRadarChartProps) {
94	  const chartData = buildChartData(data);
95	
96	  return (
97	    <div role="img" aria-label="Competitor comparison radar chart showing CRO scores across 7 pillars">
98	      <ResponsiveContainer width="100%" height={300}>
99	        <RadarChart data={chartData} margin={{ top: 10, right: 20, bottom: 10, left: 20 }}>
100	          <PolarGrid
101	            stroke="hsl(var(--border))"
102	            strokeOpacity={0.5}
103	          />
104	          <PolarAngleAxis
105	            dataKey="pillar"
106	            tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
107	            tickLine={false}
108	          />
109	          <PolarRadiusAxis
110	            angle={90}
111	            domain={[0, 100]}
112	            tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
113	            tickCount={5}
114	            stroke="hsl(var(--border))"
115	            strokeOpacity={0.3}
116	          />
117	          {data.map((series, index) => (
118	            <Radar
119	              key={series.name}
120	              name={series.name}
121	              dataKey={series.name}
122	              stroke={SERIES_COLORS[index % SERIES_COLORS.length]}
123	              fill={SERIES_COLORS[index % SERIES_COLORS.length]}
124	              fillOpacity={0.08}
125	              strokeWidth={2}
126	              dot={{ r: 3, fill: SERIES_COLORS[index % SERIES_COLORS.length] }}
127	            />
128	          ))}
129	          <Tooltip content={<CustomTooltip />} />
130	          <Legend
131	            wrapperStyle={{ fontSize: 12, paddingTop: 12 }}
132	            formatter={(value: string) => (
133	              <span style={{ color: "hsl(var(--muted-foreground))" }}>{value}</span>
134	            )}
135	          />
136	        </RadarChart>
137	      </ResponsiveContainer>
138	    </div>
139	  );
140	}
